/** Original actor studies generated by scripts/generate-actor-art.mjs.
 * 32×48 source pixels; 8 columns, transparent unused cells, ground anchor y=44.
 * These are authored prototype assets, pending the complete runtime visual gate.
 */
export type ActorAnimation={frames:number[];frameRate:number;repeat:number};
export const actorFrame={width:32,height:48,columns:8,footY:44} as const;
const frames=(row:number,count:number)=>Array.from({length:count},(_,i)=>row*8+i);
export const playerAnimations={
 idle:{frames:frames(0,4),frameRate:6,repeat:-1},
 walk:{frames:frames(1,6),frameRate:10,repeat:-1},
 run:{frames:frames(2,6),frameRate:12,repeat:-1},
 interact:{frames:frames(3,4),frameRate:8,repeat:0},
 pick_up:{frames:frames(4,6),frameRate:9,repeat:0},
 craft:{frames:frames(5,8),frameRate:10,repeat:0},
 cast:{frames:frames(6,6),frameRate:10,repeat:0},
 guard:{frames:frames(7,3),frameRate:6,repeat:0},
 hit:{frames:frames(8,3),frameRate:8,repeat:0},
 victory:{frames:frames(9,6),frameRate:8,repeat:0},
 rest:{frames:frames(10,4),frameRate:5,repeat:-1},
} satisfies Record<string,ActorAnimation>;
export const trainingAnimations={
 idle:{frames:frames(0,4),frameRate:6,repeat:-1},
 attack:{frames:frames(1,6),frameRate:10,repeat:0},
 hit:{frames:frames(2,3),frameRate:8,repeat:0},
} satisfies Record<string,ActorAnimation>;
